     @Override
     public void visit(NodeTraversal t, Node n, Node parent) {
       if (n.isExprResult()) {
         Node child = n.getFirstChild();
         switch (child.getType()) {
           case Token.ASSIGN:
             maybeCollectMember(child.getFirstChild(), child,
                 child.getLastChild());
