       JSDocInfo info = nodeWithJsDocInfo.getJSDocInfo();

       // Do nothing if there is no JSDoc type info, or
       // if the node is not a member expression, or
       // if the member expression is not of the form: this.someProperty.
       if (info == null ||
           !member.isGetProp() ||
